#include <stdio.h>

typedef unsigned long long Blockno;
typedef double Complex[2]; // Array of 2 doubles representing real and imaginary parts

int main() {
  Blockno blockNumber = 1234567890123456789;
  Complex z = {1.0, 2.0};
  printf("Block Number: %llu\n", blockNumber);
  printf("Complex Number: %lf + %lfi\n", z[0], z[1]);
  return 0;
}
